from pathlib import Path
p=Path('src/S10_sdk_deploy/s10_mpc/stair_stance_guard.py')
s=p.read_text(encoding='utf-8')
old="""    def apply(self, tau, gait_swing, com_xy, wheel_y=None, wheel_z=None, terrain_z=None, prox=None):\n"""
new="""    def apply(self, tau, gait_swing, com_xy, wheel_y=None, wheel_z=None, terrain_z=None, prox=None, wheel_ref_z=None):\n"""
s=s.replace(old,new)
old2="""        for i, act_id in enumerate(self.wheel_act_ids):\n            if request_swing[i]:\n                tau[act_id] = 0.0\n            elif contact[i]:\n                normal = max(fn[i], 0.0)\n                limit = self.mu * normal * self.wheel_radius\n                limit = min(limit, self.wheel_tau_max)\n                tau[act_id] = float(np.clip(tau[act_id], -limit, limit))\n\n        return tau\n"""
new2="""        for i, act_id in enumerate(self.wheel_act_ids):\n            if request_swing[i]:\n                tau[act_id] = 0.0\n            elif contact[i]:\n                normal = max(fn[i], 0.0)\n                limit = self.mu * normal * self.wheel_radius\n                limit = min(limit, self.wheel_tau_max)\n                tau[act_id] = float(np.clip(tau[act_id], -limit, limit))\n\n        # Deterministic swing-leg vertical tracking. If DiAL sampling does not\n        # lift an allowed swing wheel, add torque directly toward wheel_ref_z.\n        if wheel_ref_z is not None:\n            wheel_ref_z = np.asarray(wheel_ref_z, dtype=np.float64)\n            kp_z = float(__import__('os').environ.get('S10_STANCE_SWING_KP_Z', '200.0'))\n            kd_z = float(__import__('os').environ.get('S10_STANCE_SWING_KD_Z', '5.0'))\n            for i in range(4):\n                if not request_swing[i]:\n                    continue\n                err = float(wheel_ref_z[i] - wheel_z[i])\n                if err <= 0.0:\n                    continue\n                base = i * 4  # leg joint block: hipx, hipy, knee, wheel\n                hip_idx = base + 1\n                knee_idx = base + 2\n                # Empirical S10 direction: positive hipy/knee raises the wheel.\n                tau[hip_idx] += kp_z * err\n                tau[knee_idx] += kp_z * err\n                # damp using the corresponding joint velocity is optional here.\n                qd_leg = np.asarray(self.d.qvel[6:]).reshape(4, 4)\n                tau[hip_idx] -= kd_z * float(qd_leg[i, 1])\n                tau[knee_idx] -= kd_z * float(qd_leg[i, 2])\n\n        # Final leg torque clip.\n        leg_ids = (0, 1, 2, 4, 5, 6, 8, 9, 10, 12, 13, 14)\n        for j in leg_ids:\n            tau[j] = float(np.clip(tau[j], -48.0, 48.0))\n\n        return tau\n"""
s=s.replace(old2,new2)
p.write_text(s, encoding='utf-8')
print('patched guard swing torque')
